import { RoomAgentDispatch, RoomConfiguration } from "@livekit/protocol";
import { db } from "@purplefish-ai/db/server";
import { AccessToken, TrackSource } from "livekit-server-sdk";
import { z } from "zod";
import {
  AgentCallKind,
  AgentType,
  CallBuilderVersion,
  InputMetadataSchema,
} from "@/common/schemas/agent-interaction";
import { env } from "@/env";
import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { publicProcedure } from "../procedures/public-procedure";
import { router } from "../trpc";

const generateRoomToken = async (
  opportunityId: string,
  job: { id: string; schemaVersion: string },
  kind: AgentCallKind,
  participantName: string,
  inputRoomName?: string,
  ttl = "10m",
): Promise<{
  token: string;
  livekitUrl: string;
  roomName: string;
}> => {
  let roomName = inputRoomName || "";
  if (!roomName) {
    const { generateWebRoomName } = await import(
      "@/common/libs/generate-web-room-name"
    );
    roomName = generateWebRoomName({ opportunityId });
  }

  const token = new AccessToken(
    env.LIVEKIT_API_KEY_INBOUND,
    env.LIVEKIT_API_SECRET_INBOUND,
    {
      identity: participantName,
      ttl,
    },
  );
  token.addGrant({
    roomJoin: true,
    canSubscribe: true,
    canPublishSources: [TrackSource.MICROPHONE],
  });

  switch (job.schemaVersion) {
    case CallBuilderVersion.V3: {
      const metadata = InputMetadataSchema.parse({
        kind,
        opportunityId,
      });
      token.metadata = JSON.stringify(metadata);
      token.roomConfig = new RoomConfiguration({
        agents: [
          new RoomAgentDispatch({
            agentName: AgentType.ROUTING,
          }),
        ],
      });
      break;
    }
    default:
      break;
  }

  return {
    token: await token.toJwt(),
    livekitUrl: env.LIVEKIT_URL_INBOUND,
    roomName,
  };
};

export const livekitRouter = router({
  getDemoCallLivekitToken: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        opportunityId: z.string().nullable(),
      }),
    )
    .output(
      z.object({
        token: z.string(),
        livekitUrl: z.string(),
        roomName: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, jobId, opportunityId } = input;

      // Validate the user has access to the job
      const job = await db.job.findUnique({
        where: {
          id: jobId,
          organizationId: organizationId,
        },
      });

      if (!job) {
        throw new Error(`Job ${jobId} not found or user does not have access`);
      }

      // Validate the user has access to the opportunity
      if (opportunityId) {
        const opportunity = await db.opportunity.findUnique({
          where: {
            id: opportunityId,
            job: {
              id: jobId,
              organizationId: organizationId,
            },
          },
        });

        if (!opportunity) {
          throw new Error(
            `Opportunity ${opportunityId} not found or user does not have access`,
          );
        }
      }

      const roomName = opportunityId
        ? `demo:${jobId}_${opportunityId}_${new Date().getTime()}`
        : `demo:${jobId}_${new Date().getTime()}`;

      // If this room doesn't exist, it'll be automatically created when the first
      // participant joins
      // Identifier to be used for participant.
      // It's available as LocalParticipant.identity with livekit-client SDK
      const participantName = "Candidate";

      return await generateRoomToken(
        opportunityId || "",
        job,
        AgentCallKind.PLAYGROUND,
        participantName,
        roomName,
      );
    }),

  getLivekitToken: publicProcedure
    .input(
      z.object({
        secret: z.string(),
      }),
    )
    .output(
      z.object({
        token: z.string(),
        livekitUrl: z.string(),
        roomName: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { secret } = input;

      const { findValidOpportunityPublicLinkToken } = await import(
        "@/server/libs/opportunity-public-link-tokens"
      );
      const opportunityPublicLinkToken =
        await findValidOpportunityPublicLinkToken({
          token: secret,
        });

      if (!opportunityPublicLinkToken) {
        throw new Error("Invalid or expired opportunity link");
      }

      const opportunity = await db.opportunity.findUnique({
        where: {
          id: opportunityPublicLinkToken.opportunityId,
        },
        include: {
          job: {
            select: {
              id: true,
              schemaVersion: true,
            },
          },
        },
      });

      if (!opportunity) {
        throw new Error(
          `Opportunity ${opportunityPublicLinkToken.opportunityId} not found`,
        );
      }

      // If this room doesn't exist, it'll be automatically created when the first
      // participant joins
      // Identifier to be used for participant.
      // It's available as LocalParticipant.identity with livekit-client SDK
      const participantName = "Candidate";

      return await generateRoomToken(
        opportunity.id,
        opportunity.job,
        AgentCallKind.WEB,
        participantName,
      );
    }),
});

