describe("livekitRouter", () => {
  const mockOrganizationId = "org-123";
  const mockJobId = "job-123";
  const mockOpportunityId = "opp-123";
  const mockUserId = "user-123";

  beforeEach(() => {
    vi.clearAllMocks();
    mockAccessToken.metadata = undefined;
    mockAccessToken.roomConfig = undefined;
  });

  describe("getDemoCallLivekitToken", () => {
    const createMockContext = (user: any = null) => ({
      user,
      db,
    });

    const createMockCaller = (ctx: any) => {
      return {
        getDemoCallLivekitToken: async (input: any) => {
          const { organizationId, jobId, opportunityId } = input;

          if (!ctx.user || ctx.user.organizationId !== organizationId) {
            throw new TRPCError({
              code: "FORBIDDEN",
              message: "You are not a member of this organization",
            });
          }

          const job = await db.job.findUnique({
            where: {
              id: jobId,
              organizationId: organizationId,
            },
          });

          if (!job) {
            throw new Error(`Job ${jobId} not found or user does not have access`);
          }

          if (opportunityId) {
            const opportunity = await db.opportunity.findUnique({
              where: {
                id: opportunityId,
                job: {
                  id: jobId,
                  organizationId: organizationId,
                },
              },
            });

            if (!opportunity) {
              throw new Error(
                `Opportunity ${opportunityId} not found or user does not have access`,
              );
            }
          }

          const roomName = opportunityId
            ? `demo:${jobId}_${opportunityId}_${new Date().getTime()}`
            : `demo:${jobId}_${new Date().getTime()}`;

          const token = new AccessToken(
            env.LIVEKIT_API_KEY_INBOUND,
            env.LIVEKIT_API_SECRET_INBOUND,
            {
              identity: "Candidate",
              ttl: "10m",
            },
          );

          token.addGrant({
            roomJoin: true,
            canSubscribe: true,
            canPublishSources: ["microphone"],
          });

          if (job.schemaVersion === CallBuilderVersion.V3) {
            token.metadata = JSON.stringify({
              kind: AgentCallKind.PLAYGROUND,
              opportunityId: opportunityId || "",
            });
            token.roomConfig = {
              agents: [
                {
                  agentName: "routing",
                },
              ],
            };
          }

          return {
            token: await token.toJwt(),
            livekitUrl: env.LIVEKIT_URL_INBOUND,
            roomName,
          };
        },
      };
    };

