// biome-ignore-all lint/suspicious/noExplicitAny: test file

import { db } from "@purplefish-ai/db/server";
import { initTRPC } from "@trpc/server";
import superjson from "superjson";
import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  AgentCallKind,
  CallBuilderVersion,
} from "@/common/schemas/agent-interaction";
import { env } from "@/env";

vi.mock("@purplefish-ai/db/server", () => ({
  db: {
    job: {
      findUnique: vi.fn(),
    },
    opportunity: {
      findUnique: vi.fn(),
    },
  },
}));

vi.mock("@/server/libs/opportunity-public-link-tokens", () => ({
  findValidOpportunityPublicLinkToken: vi.fn(),
}));

vi.mock("@/common/libs/generate-web-room-name", () => ({
  generateWebRoomName: vi.fn().mockReturnValue("test-room-name"),
}));

const mockAccessToken = {
  addGrant: vi.fn(),
  toJwt: vi.fn().mockResolvedValue("mock-jwt-token"),
  metadata: undefined as string | undefined,
  roomConfig: undefined as any,
};

vi.mock("livekit-server-sdk", () => ({
  AccessToken: vi.fn(() => mockAccessToken),
  TrackSource: {
    MICROPHONE: "microphone",
  },
}));

vi.mock("@livekit/protocol", () => ({
  RoomAgentDispatch: vi.fn((config) => config),
  RoomConfiguration: vi.fn((config) => config),
}));

// Import the router after mocks are set up
import { livekitRouter } from "./livekit-router";

describe("livekitRouter", () => {
  const mockOrganizationId = "org-123";
  const mockJobId = "job-123";
  const mockOpportunityId = "opp-123";
  const mockUserId = "user-123";

  // Create test context and caller
  const createTestContext = (user: any = null) => ({
    user,
    db,
  });

  const t = initTRPC.context<any>().create({
    transformer: superjson,
  });
  const createCaller = t.createCallerFactory(livekitRouter);

  beforeEach(() => {
    vi.clearAllMocks();
    mockAccessToken.metadata = undefined;
    mockAccessToken.roomConfig = undefined;
  });

  describe("getDemoCallLivekitToken", () => {
    it("should generate a demo call token for a job without opportunity", async () => {
      const mockJob = {
        id: mockJobId,
        organizationId: mockOrganizationId,
        schemaVersion: CallBuilderVersion.V3,
      };

      vi.mocked(db.job.findUnique).mockResolvedValue(mockJob as any);

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: mockOrganizationId,
        role: "member",
      });

      const caller = createCaller(ctx);

      const result = await caller.getDemoCallLivekitToken({
        organizationId: mockOrganizationId,
        jobId: mockJobId,
        opportunityId: null,
      });

      expect(result).toEqual({
        token: "mock-jwt-token",
        livekitUrl: env.LIVEKIT_URL_INBOUND,
        roomName: expect.stringContaining(`demo:${mockJobId}_`),
      });

      expect(db.job.findUnique).toHaveBeenCalledWith({
        where: {
          id: mockJobId,
          organizationId: mockOrganizationId,
        },
      });

      expect(mockAccessToken.addGrant).toHaveBeenCalledWith({
        roomJoin: true,
        canSubscribe: true,
        canPublishSources: ["microphone"],
      });

      expect(mockAccessToken.metadata).toBeDefined();
      const metadata = JSON.parse(mockAccessToken.metadata);
      expect(metadata).toEqual({
        kind: AgentCallKind.PLAYGROUND,
        opportunityId: "",
      });
    });

    it("should generate a demo call token for a job with opportunity", async () => {
      const mockJob = {
        id: mockJobId,
        organizationId: mockOrganizationId,
        schemaVersion: CallBuilderVersion.V3,
      };

      const mockOpportunity = {
        id: mockOpportunityId,
        jobId: mockJobId,
      };

      vi.mocked(db.job.findUnique).mockResolvedValue(mockJob as any);
      vi.mocked(db.opportunity.findUnique).mockResolvedValue(
        mockOpportunity as any,
      );

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: mockOrganizationId,
        role: "member",
      });

      const caller = createCaller(ctx);

      const result = await caller.getDemoCallLivekitToken({
        organizationId: mockOrganizationId,
        jobId: mockJobId,
        opportunityId: mockOpportunityId,
      });

      expect(result).toEqual({
        token: "mock-jwt-token",
        livekitUrl: env.LIVEKIT_URL_INBOUND,
        roomName: expect.stringContaining(
          `demo:${mockJobId}_${mockOpportunityId}_`,
        ),
      });

      expect(db.opportunity.findUnique).toHaveBeenCalledWith({
        where: {
          id: mockOpportunityId,
          job: {
            id: mockJobId,
            organizationId: mockOrganizationId,
          },
        },
      });
    });

    it("should throw an error if user is not authorized", async () => {
      const ctx = createTestContext({
        id: mockUserId,
        organizationId: "different-org",
        role: "member",
      });

      const caller = createCaller(ctx);

      await expect(
        caller.getDemoCallLivekitToken({
          organizationId: mockOrganizationId,
          jobId: mockJobId,
          opportunityId: null,
        }),
      ).rejects.toThrow("You are not a member of this organization");
    });

    it("should throw an error if job is not found", async () => {
      vi.mocked(db.job.findUnique).mockResolvedValue(null);

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: mockOrganizationId,
        role: "member",
      });

      const caller = createCaller(ctx);

      await expect(
        caller.getDemoCallLivekitToken({
          organizationId: mockOrganizationId,
          jobId: mockJobId,
          opportunityId: null,
        }),
      ).rejects.toThrow(
        `Job ${mockJobId} not found or user does not have access`,
      );
    });

    it("should throw an error if opportunity is not found", async () => {
      const mockJob = {
        id: mockJobId,
        organizationId: mockOrganizationId,
        schemaVersion: CallBuilderVersion.V3,
      };

      vi.mocked(db.job.findUnique).mockResolvedValue(mockJob as any);
      vi.mocked(db.opportunity.findUnique).mockResolvedValue(null);

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: mockOrganizationId,
        role: "member",
      });

      const caller = createCaller(ctx);

      await expect(
        caller.getDemoCallLivekitToken({
          organizationId: mockOrganizationId,
          jobId: mockJobId,
          opportunityId: mockOpportunityId,
        }),
      ).rejects.toThrow(
        `Opportunity ${mockOpportunityId} not found or user does not have access`,
      );
    });

    it("should handle job with non-V3 schema version", async () => {
      const mockJob = {
        id: mockJobId,
        organizationId: mockOrganizationId,
        schemaVersion: "V2",
      };

      vi.mocked(db.job.findUnique).mockResolvedValue(mockJob as any);

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: mockOrganizationId,
        role: "member",
      });

      const caller = createCaller(ctx);

      const result = await caller.getDemoCallLivekitToken({
        organizationId: mockOrganizationId,
        jobId: mockJobId,
        opportunityId: null,
      });

      expect(result).toEqual({
        token: "mock-jwt-token",
        livekitUrl: env.LIVEKIT_URL_INBOUND,
        roomName: expect.stringContaining(`demo:${mockJobId}_`),
      });

      expect(mockAccessToken.metadata).toBeUndefined();
      expect(mockAccessToken.roomConfig).toBeUndefined();
    });

    it("should allow system_admin to access any organization", async () => {
      const mockJob = {
        id: mockJobId,
        organizationId: mockOrganizationId,
        schemaVersion: CallBuilderVersion.V3,
      };

      vi.mocked(db.job.findUnique).mockResolvedValue(mockJob as any);

      const ctx = createTestContext({
        id: mockUserId,
        organizationId: "different-org",
        role: "system_admin",
      });

      const caller = createCaller(ctx);

      const result = await caller.getDemoCallLivekitToken({
        organizationId: mockOrganizationId,
        jobId: mockJobId,
        opportunityId: null,
      });

      expect(result).toEqual({
        token: "mock-jwt-token",
        livekitUrl: env.LIVEKIT_URL_INBOUND,
        roomName: expect.stringContaining(`demo:${mockJobId}_`),
      });
    });
  });

  describe("getLivekitToken", () => {
    it("should generate a token for valid opportunity link", async () => {
      const mockSecret = "valid-secret-token";
      const mockOpportunityPublicLinkToken = {
        token: mockSecret,
        opportunityId: mockOpportunityId,
      };

      const mockOpportunity = {
        id: mockOpportunityId,
        job: {
          id: mockJobId,
          schemaVersion: CallBuilderVersion.V3,
        },
      };

      const { findValidOpportunityPublicLinkToken } = await import(
        "@/server/libs/opportunity-public-link-tokens"
      );

      vi.mocked(findValidOpportunityPublicLinkToken).mockResolvedValue(
        mockOpportunityPublicLinkToken as any,
      );
      vi.mocked(db.opportunity.findUnique).mockResolvedValue(
        mockOpportunity as any,
      );

      const ctx = createTestContext();
      const caller = createCaller(ctx);

      const result = await caller.getLivekitToken({
        secret: mockSecret,
      });

      expect(result).toEqual({
        token: "mock-jwt-token",
        livekitUrl: env.LIVEKIT_URL_INBOUND,
        roomName: "test-room-name",
      });

      expect(findValidOpportunityPublicLinkToken).toHaveBeenCalledWith({
        token: mockSecret,
      });

      expect(db.opportunity.findUnique).toHaveBeenCalledWith({
        where: {
          id: mockOpportunityId,
        },
        include: {
          job: {
            select: {
              id: true,
              schemaVersion: true,
            },
          },
        },
      });

      expect(mockAccessToken.metadata).toBeDefined();
      const metadata = JSON.parse(mockAccessToken.metadata);
      expect(metadata).toEqual({
        kind: AgentCallKind.WEB,
        opportunityId: mockOpportunityId,
      });
    });

    it("should throw an error for invalid opportunity link", async () => {
      const mockSecret = "invalid-secret-token";

